{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Theophylline, the closest xanthine analogue, has essentially 100% absolute oral bioavailability in healthy subjects with no first-pass effect; the query shares the same 1,3-dimethylxanthine core, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Paraxanthine, another dimethylxanthine, is rapidly and completely absorbed with high bioavailability in healthy adults, confirming that xanthine-type diones are well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Temozolomide, a methylated heterocycle with high transferability, has oral bioavailability close to 1 versus IV, supporting high oral absorption for this heterocyclic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Emtricitabine, a small polar heterocycle with high transferability, has 93% absolute oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ondansetron, a moderately absorbed heterocycle, has about 66% absolute bioavailability, still well above the 20% threshold, supporting high classification.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 7-substituted theophylline (doxofylline). The closest xanthine analogues, theophylline and paraxanthine, show essentially complete or high oral bioavailability, and other high-transfer heterocycles also exceed 20%. No affirmative low-F evidence outweighs this, so F >= 20% is supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for doxofylline itself is present in the supplied evidence; prediction relies on close xanthine analogues.",
    "Didanosine low-F records are formulation- and condition-dependent and mechanistically tied to acid-labile glycosidic bonds, making them less directly applicable to the xanthine-dioxolane scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

